{#
  The parts every platform mail is built from, imported as `c`:
    {% import "layout/parts.html" as c %}
  Each emits table-based, inline-styled markup, so it shows the same in
  old mail clients.
#}

{#- A paragraph; its text comes from a {% call %} block. -#}
{% macro para(pad=16, color="#090a05", weight="500") -%}
<tr>
  <td style="padding-bottom: {{ pad }}px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; font-size: 13px; line-height: 1.65; color: {{ color }}; font-weight: {{ weight }};">
    {{ caller() }}
  </td>
</tr>
{%- endmacro %}

{#- The greeting, such as "Hi Alice,". -#}
{% macro greeting(name) -%}
{% call para(pad=0) %}Hola, <strong>{{ name }}</strong>:{% endcall %}
{%- endmacro %}

{#- The product's name, as running copy sets it. -#}
{% macro brand() -%}
<span style="color: #9668ff; font-weight: 600">IANUA</span>
{%- endmacro %}

{#- The button the mail asks the reader to press. -#}
{% macro cta(url, label) -%}
<tr>
  <td style="padding: 8px 0 6px 0">
    <table role="presentation" cellpadding="0" cellspacing="0" border="0">
      <tr>
        <td style="border-radius: 8px; background-color: #9668ff">
          <a href="{{ url }}" target="_blank" style="display: inline-block; padding: 8px 16px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; font-size: 13px; font-weight: 600; color: #ffffff; text-decoration: none; border-radius: 8px;">{{ label }}</a>
        </td>
      </tr>
    </table>
  </td>
</tr>
{%- endmacro %}

{#- A code to type back, set large so it reads at a glance. -#}
{% macro code(value) -%}
<tr>
  <td style="padding: 8px 0 16px 0; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; font-size: 28px; font-weight: 700; letter-spacing: 6px; color: #090a05;">{{ value }}</td>
</tr>
{%- endmacro %}

