      <p class="subtitle">{{ workspace }}に進む前に、パスワードを変更する必要があります。</p>
      {{ p.note(note, {
        "link_expired": "このサインインの有効期限が切れています。パスワードを変更するには、再度サインインしてください。",
        "code_needed": "このパスワードは管理者が設定したものです。認証アプリのコードも入力してください。"
      }) }}
      <form method="post" action="{{ form_path }}">
        {%- if link_token %}
        <input type="hidden" name="token" value="{{ link_token }}">
        {%- endif %}
        {{ p.field("password", "新しいパスワード", "password", "new-password") }}
        <label for="mfa_code">認証アプリのコード（使用している場合）</label><input id="mfa_code" name="mfa_code" inputmode="numeric" autocomplete="one-time-code">
        {{ p.return_to(return_to) }}
        {{ p.submit("パスワードを変更") }}
      </form>
      {{ p.link("ご本人ではありませんか？", log_in_path, "再度サインイン") }}
{% endblock %}

