{% block title %}შექმენით ანგარიში {{ workspace }}-ში{% endblock %}

{% block content %}
      <h1>შექმენით თქვენი ანგარიში</h1>
      <p class="subtitle">შემოუერთდით {{ workspace }}-ს. მისამართის დასადასტურებელ ბმულს ელფოსტით გამოგიგზავნით.</p>
      {{ p.note(note, {
        "not_allowed": "ეს ტენანტი რეგისტრაციას არ იღებს.",
        "invalid": "შეამოწმეთ შეყვანილი მონაცემები. პაროლი შესაძლოა ზედმეტად მოკლე ან გავრცელებულია."
      }) }}
      <form method="post" action="{{ form_path }}">
        {{ p.field("display_name", "თქვენი სახელი", "text", "name") }}
        {{ p.field("email", "ელფოსტის მისამართი", "email", "email") }}
        {{ p.field("password", "პაროლი", "password", "new-password") }}
        {{ p.submit("ანგარიშის შექმნა") }}
      </form>
      {{ p.link("უკვე გაქვთ ანგარიში?", log_in_path, "შესვლა") }}
{% endblock %}

